if(name==='passport'){gate('PASSPORT_VIEW');try{const id=el.dataset.id,p=L.passport(db,id),m=db.members.find(v=>v.id===id);if(!m)return alert('Membre introuvable.');const blocks=p.map(v=>{const sch=L.schedule(db,v.application.id),decision=v.decision?.decision||'—';const events=[...(v.payments||[]).map(x=>({at:x.at,label:`Paiement ${money(x.amount)}`,detail:`${x.method||'Caisse'}${x.reference?' · '+x.reference:''}`,kind:'paiement'})),...(v.restructures||[]).map(x=>({at:x.at,label:'Restructuration',detail:`${x.reason||'Motif non renseigné'}${x.evidence?' · preuve '+x.evidence:''}`,kind:'incident'})),...(v.followups||[]).map(x=>({at:x.at,label:x.type||'Suivi',detail:`${x.note||''}${x.nextAction?' · action : '+x.nextAction:''}${x.nextDate?' · '+x.nextDate:''}`,kind:'suivi'}))].sort((a,b)=>String(a.at).localeCompare(String(b.at)));return `<section class="passport-credit"><h4>${esc(v.application.id)} · ${esc(v.application.product)} · ${esc(v.application.status)}</h4><div class="timeline"><span>Demande ${money(v.application.requestedAmount)}</span><span>Décision ${esc(decision)}</span><span>Décaissement ${money(v.position.disbursed)}</span><span>Encours ${money(v.position.outstanding)}</span></div><h5>Historique des paiements</h5><div class="table"><table><thead><tr><th>Échéance</th><th>Prévu</th><th>Payé</th><th>Reste</th><th>Date prévue</th><th>Jours retard</th><th>Statut</th></tr></thead><tbody>${sch.length?sch.slice(0,24).map(e=>{const paid=Math.max(0,(e.total||0)-(e.balance ?? (e.total||0))),balance=e.balance ?? (e.total||0),delay=e.dueDate&&new Date(e.dueDate)<new Date()&&balance>0?Math.max(0,Math.floor((Date.now()-new Date(e.dueDate))/86400000)):0,status=balance<=0?'Payé':paid>0?'Partiel':delay?'Retard':'À venir';return `<tr><td>${e.number||'—'}</td><td>${money(e.total||0)}</td><td>${money(paid)}</td><td>${money(balance)}</td><td>${esc(e.dueDate||'—')}</td><td>${delay}</td><td>${status}</td></tr>`}).join(''):'<tr><td colspan="7">Aucun échéancier pour ce dossier.</td></tr>'}</tbody></table></div><h5>Événements, incidents & régularisations</h5><div class="payment-events">${events.length?events.map(x=>`<div class="row"><span><b>${esc(x.label)}</b><br><small>${esc(x.detail)}</small></span><small>${x.at?new Date(x.at).toLocaleDateString('fr-FR'):'—'}</small></div>`).join(''):'<p>Aucun événement enregistré.</p>'}</div><p><b>Traçabilité :</b> ${(v.restructures||[]).length} restructuration(s) · ${(v.payments||[]).length} paiement(s) · ${(v.followups||[]).length} action(s) de suivi.</p></section>`}).join('');return infoModal('Passeport financier — '+m.name,`<div class="passport-summary-head"><div><small>N° membre</small><b>${esc(m.memberNo)}</b></div><div><small>Membre depuis</small><b>${esc(m.joinedAt||'—')}</b></div><div><small>Activité</small><b>${esc(m.activity||'—')}</b></div><div><small>Demandes</small><b>${p.length}</b></div></div><div class="passport-canvas"><div class="timeline master"><span>Adhésion</span><span>Demandes ${p.length}</span><span>Crédits</span><span>Paiements</span><span>Incidents</span><span>Régularisations</span><span>Historique</span></div>${blocks||'<div class="empty-state">Aucun dossier de crédit enregistré pour ce membre.</div>'}</div>`,{size:'xwide'})}catch(err){console.error('Passeport financier',err);alert('Impossible d’ouvrir le passeport financier : '+(err?.message||err));return}}
