function updateCopilotContext(){const label=$('#copilotContext'),mode=$('#copilotMode');if(label){if(active){try{const d=L.dossier(db,active);label.textContent=`${d.application.id} · ${d.member.name} · ${d.application.product}`}catch{label.textContent='Dossier non accessible'}}else label.textContent='Contexte général CREDIPASS'}if(mode)mode.textContent=connectionState()==='HORS_CONNEXION'?'Mode hors connexion — assistant local':'Assistant CREDIPASS disponible · mode local sécurisé si IA externe absente';}
function hideGlobalSearchResults(){const box=$('#globalSearchResults');if(box){box.hidden=true;box.innerHTML=''}}
function renderGlobalSearchResults(query){const box=$('#globalSearchResults');if(!box)return;const q=String(query||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');if(q.length<2){hideGlobalSearchResults();return}const norm=v=>String(v??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const ms=visibleMembers(currentUser,db).filter(m=>norm([m.memberNo,m.name,m.phone,m.city,m.activity].join(' ')).includes(q)).slice(0,4),apps=visibleApplications(currentUser,db).filter(a=>{const m=db.members.find(x=>x.id===a.memberId);return norm([a.id,a.product,a.purpose,a.status,m?.name,m?.memberNo].join(' ')).includes(q)}).slice(0,4);if(!ms.length&&!apps.length){box.innerHTML='<div class="search-empty">Aucun résultat.</div>';box.hidden=false;return}box.innerHTML=`${ms.map(m=>`<button data-act="searchMember" data-id="${esc(m.id)}"><span><b>${esc(m.name)}</b><small>${esc(m.memberNo)} · ${esc(m.city)}</small></span><em>Membre</em></button>`).join('')}${apps.map(a=>{const m=db.members.find(x=>x.id===a.memberId);return `<button data-act="searchApp" data-id="${esc(a.id)}"><span><b>${esc(a.id)} · ${esc(m?.name||'')}</b><small>${esc(a.product)} · ${esc(a.status)}</small></span><em>Dossier</em></button>`}).join('')}`;box.hidden=false}
document.addEventListener('submit',e=>{if(e.target.id==='copilotForm'){e.preventDefault();const q=$('#copilotQuestion')?.value?.trim();if(q){act('copilotAsk',{dataset:{question:q}});$('#copilotQuestion').value=''}}});
document.addEventListener('submit',async e=>{const f=e.target;if(f?.id!=='profilePageForm'&&f?.id!=='passwordPageForm')return;e.preventDefault();try{await(f.id==='profilePageForm'?submitProfilePage(f):submitPasswordPage(f))}catch(err){alert(err.message)}});
document.addEventListener('submit',e=>{if(e.target?.id!=='memberPageForm')return;e.preventDefault();try{submitMemberPage(e.target)}catch(err){alert(err.message)}});
document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){view=n.dataset.nav;active=null;render();return}const a=e.target.closest('[data-act]');if(a)act(a.dataset.act,a)});
$('#copilotFab')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();toggleCopilot()});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch')?.focus();return}if(e.key==='Escape'){if(!$('#copilotDrawer')?.hidden)setCopilotOpen(false);hideGlobalSearchResults()}});document.addEventListener('input',e=>{if(e.target.id==='memberSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('tr[data-search]').forEach(r=>r.hidden=!r.dataset.search.includes(q))}if(e.target.id==='globalSearch')renderGlobalSearchResults(e.target.value)});window.addEventListener('error',e=>{const b=$('#bootError');if(b){b.textContent='Erreur : '+e.message;b.hidden=false}});
function friendlyNetworkError(err){const m=String(err?.message||err||'');if(/Failed to fetch|fetch failed|NetworkError|Load failed/i.test(m))return 'Serveur CREDIPASS inaccessible. Vérifiez la fenêtre serveur et /api/health. Si le serveur ne démarre pas, vérifiez PostgreSQL avec « npm run db:check ».';return m||'Erreur inconnue.'}
const login=$('#institutionLogin'), loginScreen=$('#loginScreen'), appShell=$('#appShell');
function enterInstitution(user){currentUser=user||currentUser;loginScreen.hidden=true;appShell.hidden=false;sessionStorage.setItem('credipass-institution-user',JSON.stringify(currentUser));refreshUserHeader();render()}
function refreshUserHeader(){$('#userName').textContent=currentUser.name;const agency=$('#userAgency');if(agency)agency.textContent=currentUser.agency;const avatar=$('#userAvatar');if(avatar)avatar.textContent=initials(currentUser.name)}
async function leaveInstitution(){sessionStorage.removeItem('credipass-institution-user');await apiLogout();currentUser=null;appShell.hidden=true;loginScreen.hidden=false}
login?.addEventListener('submit',async e=>{e.preventDefault();const u=$('#loginUser').value.trim(),p=$('#loginPass').value;try{if(connectionState()==='HORS_CONNEXION'){const cached=await verifyOfflineLogin(u,p);enterInstitution(cached);return}const user=await apiLogin(u,p);enterInstitution(user)}catch(err){alert(friendlyNetworkError(err)||'Identifiant ou mot de passe incorrect.')}});
$('#logoutBtn')?.addEventListener('click',leaveInstitution);

async function restoreInstitutionSession(){let saved=null;try{saved=JSON.parse(sessionStorage.getItem('credipass-institution-user')||'null')}catch{}if(!saved)return;if(connectionState()==='HORS_CONNEXION'){enterInstitution(saved);return}const verified=await apiMe();if(verified)enterInstitution(verified);else sessionStorage.removeItem('credipass-institution-user')}
restoreInstitutionSession().catch(()=>sessionStorage.removeItem('credipass-institution-user'));
L.hydrate().then(x=>{db=ensureSfdFieldConfig(normalizeTerritory(ensureCatalog(normalizeScope(x))));if(!appShell.hidden)render()}).catch(()=>{});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());window.addEventListener('credipass-connectivity',()=>render());
